<?php
/**
 * Repairs embedded JSON-LD blocks whose backslash escapes were stripped.
 *
 * THE BUG WAS MINE, AND IT IS A WORDPRESS TRAP WORTH KNOWING.
 * wp_update_post() and wp_insert_post() expect SLASHED data — they call
 * wp_unslash() on what you hand them. Passing raw post_content that contains a
 * literal backslash silently loses it. Inside an embedded JSON-LD block, every
 * \" collapses to " and the block stops parsing.
 *
 * bin/fix-redirect-hops.php rewrote hrefs in post_content and wrote back with a
 * bare wp_update_post(). On four pages the content happened to contain an inline
 * <script type="application/ld+json"> FAQPage block with escaped quotes inside
 * answer text — Berkeley County's \"Charleston, SC 29492\" mailing address, a
 * rideshare \"Period 3\" — and those escapes were stripped. The href rewrite
 * itself was correct; the write was not.
 *
 *   4723, 4742, 4758, 5126   valid before that pass, invalid after — I broke them
 *   4713, 4766               already invalid beforehand, repaired here too
 *
 * PROOF THE REPAIR IS EXACT, not a reconstruction. For the four I broke, taking
 * the pre-edit backup block and deleting every backslash yields the CURRENT block
 * byte for byte. The damage is therefore purely the lost escapes and nothing else
 * — no intended edit landed inside those blocks — so the backup block is restored
 * verbatim rather than re-derived.
 *
 * The other two have no valid snapshot, so they are re-escaped in place: a quote
 * inside a string is structural when the next non-space character is , : } or ],
 * and literal otherwise. Both parse afterwards and both yield a FAQPage with six
 * questions.
 *
 * THIS SCRIPT USES wp_slash(). Every other script in bin/ that writes
 * post_content does not — 43 of them. Most are spent one-shots, but the rule now
 * belongs in CLAUDE.md rather than in each author's memory.
 *
 * Run:  ssh $H "wp --path=... eval-file -" < bin/repair-jsonld-backslash-damage.php
 *       (append ` apply` to write; default is a dry run)
 */

$APPLY = ( isset( $args[0] ) && 'apply' === $args[0] );
$FIX   = json_decode( base64_decode( '' ), true );
if ( ! is_array( $FIX ) ) { echo "DECODE FAILED\n"; return; }

$backup = array(); $ok = true; $n = 0;

foreach ( $FIX as $id => $f ) {
	$id = (int) $id;
	$c  = get_post_field( 'post_content', $id );

	if ( false === strpos( $c, $f['broken'] ) ) {
		echo "REFUSE $id — current block does not match the recorded broken text\n"; $ok = false; continue;
	}
	if ( null === json_decode( $f['fixed'], true ) ) {
		echo "REFUSE $id — replacement does not parse\n"; $ok = false; continue;
	}

	$backup[] = array( 'id' => $id, 'surface' => 'post_content', 'before' => $c );
	$n++;
	printf( "%s %-6d %s\n", $APPLY ? 'APPLY ' : 'DRYRUN', $id, $f['how'] );

	if ( ! $APPLY ) { continue; }

	$new = str_replace( $f['broken'], $f['fixed'], $c );

	// wp_slash() is the entire point of this script.
	$r = wp_update_post( wp_slash( array( 'ID' => $id, 'post_content' => $new ) ), true );
	if ( is_wp_error( $r ) ) { echo "   ERROR " . $r->get_error_message() . "\n"; $ok = false; }
}

if ( $APPLY ) {
	echo "\n--- verify: every embedded block on the site ---\n";
	global $wpdb;
	$ids = $wpdb->get_col( "SELECT ID FROM {$wpdb->posts} WHERE post_status='publish' AND post_content LIKE '%application/ld+json%'" );
	$tot = 0; $bad = 0;
	foreach ( $ids as $pid ) {
		$c = get_post_field( 'post_content', $pid );
		if ( ! preg_match_all( '#<script type="application/ld\+json">(.*?)</script>#is', $c, $m ) ) { continue; }
		foreach ( $m[1] as $blk ) {
			$tot++;
			json_decode( trim( $blk ), true );
			if ( JSON_ERROR_NONE !== json_last_error() ) {
				$bad++;
				printf( "  STILL INVALID: %d %s\n", $pid, wp_make_link_relative( get_permalink( $pid ) ) );
			}
		}
	}
	printf( "blocks: %d   invalid: %d\n", $tot, $bad );
	if ( $bad ) { $ok = false; }
}

echo "\n" . wp_json_encode( array( 'applied' => $APPLY, 'posts' => $n, 'ok' => $ok ) ) . "\n";

if ( ! $APPLY ) {
	echo "\n--- backup payload ---\n";
	$j = wp_json_encode( $backup, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE );
	echo ( false === $j ) ? 'ENCODE FAILED' : $j;
	echo "\n";
}
